Arguments: {"cwd":null,"code":"const tabId = 343605414;

const res = await browserjs(tabId, () => {
  // Let's find all links to /vehicle/
  const vehicleLinks = Array.from(document.querySelectorAll('a[href*="/vehicle/"]'));
  // For each link, find its top-level tile container (under the grid)
  const results = [];
  for (const a of vehicleLinks) {
    // Find the vehicle card container
    let cur = a;
    while (cur && cur.parentElement && cur.parentElement !== document.body) {
      if (cur.parentElement.children.length > 2 && cur.parentElement.className.includes('grid')) {
        break;
      }
      cur = cur.parentElement;
    }
    results.push({
      href: a.href,
      fullText: cur ? cur.innerText : a.innerText
    });
  }
  return results;
});

console.log("Vehicle links count:", res.length);
// Deduplicate by href
const seen = new Set();
const deduped = [];
for (const r of res) {
  const id = r.href.split("?")[0];
  if (!seen.has(id)) {
    seen.add(id);
    deduped.push({ href: id, text: r.fullText });
  }
}

console.log("Deduped count:", deduped.length);
deduped.forEach((d, i) => {
  console.log(`Car #${i+1}: ${d.href}`);
  console.log(d.text.replace(/\n+/g, " | "));
});
","title":"Extract all vehicle cards text"}
